class Fail(Exception): pass

def place_order(steps):
    done = []
    try:
        for name, do, undo in steps:
            do(); done.append((name, undo)); print("ok  ", name)
    except Fail as e:
        print("fail", e)
        for name, undo in reversed(done):
            undo(); print("undo", name)
        return "FAILED"
    return "PAID"

stock, coupon = {"티셔츠": 3}, {"C1": "UNUSED"}
def pay(): raise Fail("결제 승인 거절")
print(place_order([
    ("재고 차감", lambda: stock.update(티셔츠=stock["티셔츠"] - 1), lambda: stock.update(티셔츠=stock["티셔츠"] + 1)),
    ("쿠폰 사용", lambda: coupon.update(C1="USED"), lambda: coupon.update(C1="UNUSED")),
    ("결제 승인", pay, lambda: None),
]))
print(stock, coupon)

