results, orders = {}, []

def create_order(idem_key, body):
    if idem_key in results:
        return results[idem_key]
    order_id = f"O{len(orders) + 1}"
    orders.append(order_id)
    results[idem_key] = {"order_id": order_id, "amount": body["amount"]}
    return results[idem_key]

print(create_order("k-123", {"amount": 34800}))
print(create_order("k-123", {"amount": 34800}))  # 두 번 누름 / 재시도
print("만들어진 주문 수", len(orders))

