NEXT = {
    "결제완료": {"상품준비중", "발송지연", "결제취소"},
    "상품준비중": {"배송중", "발송지연", "결제취소"},
    "발송지연": {"배송중", "결제취소"},
    "배송중": {"배송완료"},
    "배송완료": {"구매확정", "반품처리중", "교환처리중"},
    "구매확정": set(),
}

def move(state, to):
    if to not in NEXT.get(state, set()):
        raise ValueError(f"{state} → {to} 은 안 된다")
    return to

s = "결제완료"
for to in ["상품준비중", "배송중", "배송완료", "구매확정"]:
    s = move(s, to); print(s)
for bad in [("배송중", "상품준비중"), ("구매확정", "반품처리중")]:
    try: move(*bad)
    except ValueError as e: print(e)

